   512	void VC5Decompressor::Wavelet::HighPassBand::decode(const Wavelet& wavelet) {
   513	  auto dequantize = [quant = quant](int16_t val) -> int16_t {
   514	    return mVC5DecompandingTable[uint16_t(val)] * quant;
   515	  };
   516	
   517	  data = Array2DRef<int16_t>::create(wavelet.width, wavelet.height);
   518	  const Array2DRef<int16_t> dst(data.data(), wavelet.width, wavelet.height);
   519	
   520	  BitPumpMSB bits(bs);
   521	  // decode highpass band
   522	  int pixelValue = 0;
   523	  unsigned int count = 0;
   524	  int nPixels = wavelet.width * wavelet.height;
   525	  for (int iPixel = 0; iPixel < nPixels;) {
   526	    getRLV(&bits, &pixelValue, &count);
   527	    for (; count > 0; --count) {
   528	      if (iPixel > nPixels)
   529	        ThrowRDE("Buffer overflow");
   530	      data[iPixel] = dequantize(pixelValue);
   531	      ++iPixel;
   532	    }
   533	  }
   534	  if (bits.getPosition() < bits.getSize()) {
   535	    getRLV(&bits, &pixelValue, &count);
   536	    if (pixelValue != MARKER_BAND_END || count != 0)
   537	      ThrowRDE("EndOfBand marker not found");
   538	  }
   539	}
